def ensure_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)


def read_json(path: Path) -> dict[str, Any]:
    if not path.exists() or path.is_dir():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists() or path.is_dir():
        return []
    rows: list[dict[str, Any]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        text = line.strip()
        if not text:
            continue
        try:
            payload = json.loads(text)
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict):
            rows.append(payload)
    return rows


def read_csv(path: Path) -> list[dict[str, str]]:
    if not path.exists() or path.is_dir():
        return []
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def write_json(path: Path, data: Any) -> None:
    ensure_dir(path.parent)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")


def write_text(path: Path, text: str) -> None:
    ensure_dir(path.parent)
    path.write_text(text, encoding="utf-8")


def write_csv(path: Path, rows: list[dict[str, Any]], fieldnames: list[str] | None = None) -> None:
    ensure_dir(path.parent)
    if fieldnames is None:
        fieldnames = []
        seen: set[str] = set()
        for row in rows:
            for key in row:
                if key not in seen:
                    fieldnames.append(key)
                    seen.add(key)
    with path.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow({key: row.get(key, "") for key in fieldnames})


def rel(path: Path) -> str:
    return path.as_posix()


def exists(path: Path) -> bool:
    return path.exists()


def bval(value: Any) -> bool:
    return str(value).strip().lower() in {"true", "1", "yes", "y"}


def fnum(value: Any, default: float = math.nan) -> float:
    try:
        if value is None or value == "":
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def finite(value: Any) -> bool:
    return math.isfinite(fnum(value))


def semantic_label_id(value: Any) -> int | None:
    val = fnum(value)
    if not math.isfinite(val):
        return None
    return int(val)


def semantic_label_name(label_id: Any) -> str:
    lid = semantic_label_id(label_id)
    if lid is None:
        return ""
    return SEMANTIC_FINE_ID_TO_LABEL.get(lid, f"unknown_fine_label_{lid}")


def semantic_label_role(label_id: Any) -> str:
    lid = semantic_label_id(label_id)
    if lid is None:
        return "unknown"
    name = semantic_label_name(lid)
    if lid in SEMANTIC_FINE_MOVABLE_IDS:
        return "dynamic_object_reject"
    if lid in SEMANTIC_FINE_SKY_IDS:
        return "sky_context_reject"
    if lid in SEMANTIC_FINE_VEGETATION_IDS:
        return "vegetation_context_or_weak"
    if lid in SEMANTIC_FINE_STRUCTURE_IDS:
        if name in {"road", "sidewalk", "ground", "floor", "crosswalk"}:
            return "road_edge_or_ground_structure"
        return "stable_structure"
    return "unknown_or_other"


def semantic_role_scale_evidence_allowed(role: str) -> bool:
    return role in {"stable_structure", "road_edge_or_ground_structure"}


def metric_gate_pass(row: dict[str, Any]) -> bool:
    return (
        fnum(row.get("bad_recall")) >= 0.65
        and fnum(row.get("good_FPR")) <= 0.25
        and abs(fnum(row.get("corr_with_L3"))) >= 0.50
        and fnum(row.get("selected_positive_sequence_coverage")) >= 3
        and fnum(row.get("same_count_random_margin")) >= 0.05
    )


def index_cases(rows: Iterable[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    for row in rows:
        case_id = str(row.get("case_id", "")).strip()
        if case_id and case_id not in out:
            out[case_id] = row
    return out


def case_set(rows: Iterable[dict[str, Any]]) -> set[str]:
    return {str(row.get("case_id", "")).strip() for row in rows if str(row.get("case_id", "")).strip()}


def split_labels(value: str) -> set[str]:
    return {x.strip() for x in str(value).replace(",", ";").split(";") if x.strip()}


def mean(values: Iterable[float]) -> float:
    xs = [x for x in values if math.isfinite(x)]
    if not xs:
        return math.nan
    return sum(xs) / len(xs)


def median(values: Iterable[float]) -> float:
    xs = sorted(x for x in values if math.isfinite(x))
    if not xs:
        return math.nan
    n = len(xs)
    mid = n // 2
    if n % 2:
        return xs[mid]
    return (xs[mid - 1] + xs[mid]) / 2.0


def pearson(xs: list[float], ys: list[float]) -> float:
    pairs = [(x, y) for x, y in zip(xs, ys) if math.isfinite(x) and math.isfinite(y)]
    if len(pairs) < 2:
        return math.nan
    mx = sum(x for x, _ in pairs) / len(pairs)
    my = sum(y for _, y in pairs) / len(pairs)
    vx = sum((x - mx) ** 2 for x, _ in pairs)
    vy = sum((y - my) ** 2 for _, y in pairs)
    if vx <= 0 or vy <= 0:
        return math.nan
    cov = sum((x - mx) * (y - my) for x, y in pairs)
    return cov / math.sqrt(vx * vy)


def finite_mean(row: dict[str, Any], keys: list[str]) -> float:
    return mean(fnum(row.get(key)) for key in keys)


def rank_norm(values: dict[str, float], reverse: bool = False) -> dict[str, float]:
    finite_items = [(k, v) for k, v in values.items() if math.isfinite(v)]
    if not finite_items:
        return {k: math.nan for k in values}
    finite_items.sort(key=lambda kv: kv[1], reverse=reverse)
    n = len(finite_items)
    if n == 1:
        return {finite_items[0][0]: 0.5}
    out = {}
    for idx, (key, _value) in enumerate(finite_items):
        out[key] = idx / (n - 1)
    return {k: out.get(k, math.nan) for k in values}


def safe_score_mean(*values: float) -> float:
    return mean(values)


