def build_stage5_branch_c() -> dict[str, Any]:
    out = ROOT / "stage5_branch_c_same_space_state_machine"
    role_summary = read_json(PATHS["v101_trackW_summary"])
    state_summary = read_json(PATHS["v101_trackS2_summary"])
    q2_summary = read_json(PATHS["v101_trackQ2_summary"])
    role_rows = read_csv(PATHS["v101_trackW_rows"])
    state_rows = read_csv(PATHS["v101_trackS2_rows"])
    identity_audit = build_branch_c_identity_fail_forward(out)
    inventory_rows = [
        {
            "source": rel(PATHS["v101_trackW_summary"]),
            "component": "role_assignment",
            "gate_pass": role_summary.get("gate_pass", False),
            "proxy_only": role_summary.get("proxy_only", True),
            "row_count": role_summary.get("role_row_count", len(role_rows)),
            "identity_resolution_level": "semantic_class_fallback" if role_rows else "",
            "runtime_action_allowed": role_summary.get("runtime_action_allowed", False),
        },
        {
            "source": rel(PATHS["v101_trackS2_summary"]),
            "component": "state_estimator",
            "gate_pass": state_summary.get("gate_pass", False),
            "proxy_only": state_summary.get("proxy_only", True),
            "row_count": state_summary.get("state_row_count", len(state_rows)),
            "identity_resolution_level": "semantic_class_fallback" if state_rows else "",
            "runtime_action_allowed": state_summary.get("runtime_action_allowed", False),
            "blocker": state_summary.get("blocker", ""),
        },
        {
            "source": rel(PATHS["v101_trackQ2_summary"]),
            "component": "chunk_level_admission_dependency",
            "gate_pass": q2_summary.get("gate_pass", False),
            "proxy_only": q2_summary.get("proxy_only", True),
            "true_stage_pass": q2_summary.get("true_stage_pass", False),
            "runtime_action_allowed": q2_summary.get("runtime_action_allowed", False),
            "blocker": q2_summary.get("blocker", ""),
        },
    ]
    write_csv(out / "branch_c_state_machine_inventory_rows.csv", inventory_rows)
    stage5_pass = (
        bval(role_summary.get("gate_pass"))
        and bval(state_summary.get("gate_pass"))
        and not bval(role_summary.get("proxy_only"))
        and not bval(state_summary.get("proxy_only"))
        and bval(q2_summary.get("true_stage_pass"))
    )
    report = [
        "# ACL2 v103 Stage5 Branch C same-space state-machine report",
        "",
        "```text",
        f"role_assignment_gate_pass={role_summary.get('gate_pass')}",
        f"role_assignment_proxy_only={role_summary.get('proxy_only')}",
        f"state_estimator_gate_pass={state_summary.get('gate_pass')}",
        f"state_estimator_proxy_only={state_summary.get('proxy_only')}",
        f"q2_true_stage_pass={q2_summary.get('true_stage_pass')}",
        f"identity_resolution_level=semantic_class_fallback_plus_diagnostic_stage_c_seed_lifecycle",
        f"identity_audit_source_count={identity_audit.get('identity_audit_source_count')}",
        f"strict_instance_identity_row_count={identity_audit.get('strict_instance_identity_row_count')}",
        f"stage_c_seed_or_component_row_count={identity_audit.get('stage_c_seed_or_component_row_count')}",
        f"masklet_or_instance_column_count={identity_audit.get('masklet_or_instance_column_count')}",
        f"diagnostic_component_provider_available={identity_audit.get('diagnostic_component_provider_available')}",
        f"v102_target_lifecycle_case_coverage={identity_audit.get('v102_target_lifecycle_case_coverage')}",
        f"strict_component_provider_action_ready={identity_audit.get('strict_component_provider_action_ready')}",
        f"stage5_branch_c_diagnostic_pass={stage5_pass}",
        "```",
        "",
        "Interpretation: role assignment materialized and v101 TrackW proxy gate passes. The v103 v5 fail-forward now also imports v101 diagnostic lifecycle/component visibility rows for all v102 target cases. Branch C still does not pass because the state estimator gate is false, rows remain proxy/semantic-class or diagnostic seed/component level, direct action-ready anchor-component mapping is absent, and Q2 true-stage admission is blocked.",
    ]
    write_text(out / "branch_c_state_machine_report.md", "\n".join(report) + "\n")
    summary = {
        "schema": "acl2_v103_stage5_branch_c_summary_v2",
        "stage": 5,
        "branch": "C_same_space_semantic_anchor_state_machine",
        "stage5_branch_c_diagnostic_pass": stage5_pass,
        "role_assignment_gate_pass": role_summary.get("gate_pass", False),
        "role_assignment_proxy_only": role_summary.get("proxy_only", True),
        "role_row_count": role_summary.get("role_row_count", len(role_rows)),
        "state_estimator_gate_pass": state_summary.get("gate_pass", False),
        "state_estimator_proxy_only": state_summary.get("proxy_only", True),
        "state_row_count": state_summary.get("state_row_count", len(state_rows)),
        "q2_true_stage_pass": q2_summary.get("true_stage_pass", False),
        "identity_resolution_level": "semantic_class_fallback_plus_diagnostic_stage_c_seed_lifecycle",
        **identity_audit,
        "runtime_action_allowed": False,
        "full_validation_run": False,
        "blocker": "Branch C now has diagnostic anchor-seed lifecycle/component visibility provider evidence, but it is not strict action-ready instance identity: direct anchor->Stage-C seed matches remain zero, true current support is false, and state estimator/Q2 true-stage gates do not pass.",
        "outputs": {
            "state_machine_inventory_rows": rel(out / "branch_c_state_machine_inventory_rows.csv"),
            "identity_provider_audit_rows": identity_audit.get("identity_provider_audit_rows", ""),
            "identity_resolution_fail_forward_report": identity_audit.get("identity_resolution_fail_forward_report", ""),
            "lifecycle_component_provider_rows": identity_audit.get("lifecycle_component_provider_rows", ""),
            "lifecycle_component_provider_report": identity_audit.get("lifecycle_component_provider_report", ""),
            "state_machine_report": rel(out / "branch_c_state_machine_report.md"),
        },
    }
    write_json(out / "stage5_summary.json", summary)
    return summary


