        f"focused_good_control_case_count={summary['tracked_instance_query_soft_direct_match_control_focused_good_control_case_count']}",
        f"focused_good_control_available_case_count={summary['tracked_instance_query_soft_direct_match_control_focused_good_control_available_case_count']}",
