        f"carrier_good_control_candidate_pass_count={summary['tracked_instance_query_soft_direct_match_control_carrier_good_control_candidate_pass_count']}",
        f"best_rule_name={summary['tracked_instance_query_soft_direct_match_control_best_rule_name']}",
        f"best_direct_match_mode={summary['tracked_instance_query_soft_direct_match_control_best_direct_match_mode']}",
        f"best_selected_case_ids={summary['tracked_instance_query_soft_direct_match_control_best_selected_case_ids']}",
        f"best_selected_bad_case_count={summary['tracked_instance_query_soft_direct_match_control_best_selected_bad_case_count']}",
        f"best_selected_good_case_count={summary['tracked_instance_query_soft_direct_match_control_best_selected_good_case_count']}",
        f"best_action_metric_coverage_pass={summary['tracked_instance_query_soft_direct_match_control_best_action_metric_coverage_pass']}",
