        f"best_carrier_rule_name={summary['tracked_instance_query_soft_direct_match_control_best_carrier_rule_name']}",
        f"best_carrier_direct_match_mode={summary['tracked_instance_query_soft_direct_match_control_best_carrier_direct_match_mode']}",
        f"best_carrier_selected_case_ids={summary['tracked_instance_query_soft_direct_match_control_best_carrier_selected_case_ids']}",
        f"best_carrier_selected_bad_case_count={summary['tracked_instance_query_soft_direct_match_control_best_carrier_selected_bad_case_count']}",
        f"best_carrier_selected_good_case_count={summary['tracked_instance_query_soft_direct_match_control_best_carrier_selected_good_case_count']}",
        f"best_carrier_action_metric_coverage_pass={summary['tracked_instance_query_soft_direct_match_control_best_carrier_action_metric_coverage_pass']}",
        f"best_carrier_action_metric_missing_case_ids={summary['tracked_instance_query_soft_direct_match_control_best_carrier_action_metric_missing_case_ids']}",
