def main() -> None:
    ensure_dir(ROOT)
    stage0 = build_stage0()
    stage1 = build_stage1()
    stage2 = build_stage2()
    stage3b = build_stage3_branch_b()
    stage4a = build_stage4_branch_a(stage3b)
    stage5c = build_stage5_branch_c()
    stage6d = build_stage6_branch_d()
    stage7 = build_stage7_read_provider()
    stage8 = build_stage8_cue_distillation_blocked(stage3b, stage4a, stage5c, stage6d, stage7)
    stage9 = build_stage9_runtime_pilot_blocked(stage8, stage4a)
    decision = build_final_decision(stage0, stage1, stage2, stage3b, stage4a, stage5c, stage6d, stage7, stage8, stage9)
    print(json.dumps(
        {
            "root": rel(ROOT),
            "stage0_pass": stage0.get("stage0_pass"),
            "stage1_pass": stage1.get("stage1_pass"),
            "stage2_feature_materialization_pass": stage2.get("stage2_feature_materialization_pass"),
            "stage3_branch_b_oracle_pass": stage3b.get("branch_b_oracle_pass"),
            "stage4_branch_a_action_surface_pass": stage4a.get("stage4_branch_a_action_surface_pass"),
            "stage5_branch_c_diagnostic_pass": stage5c.get("stage5_branch_c_diagnostic_pass"),
            "stage6_branch_d_ttt_lifecycle_pass": stage6d.get("stage6_branch_d_ttt_lifecycle_pass"),
            "stage7_read_provider_integration_pass": stage7.get("stage7_read_provider_integration_pass"),
            "stage8_cue_distillation_pass": stage8.get("stage8_cue_distillation_pass"),
            "stage9_runtime_pilot_run": stage9.get("stage9_runtime_pilot_run"),
            "semantic_increment_pass": stage3b.get("semantic_increment_pass"),
            "focused_case_count": stage1.get("focused_case_count"),
            "missing_feature_row_count": stage2.get("missing_feature_row_count"),
            "runtime_action_allowed": decision.get("runtime_action_allowed"),
            "goal_achieved": decision.get("goal_achieved"),
        },
        ensure_ascii=False,
        indent=2,
        sort_keys=True,
    ))


if __name__ == "__main__":
    main()
